// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(uint256 initialBalance) public {
        initialBalance = bound(initialBalance, 1, type(uint128).max);
        vm.deal(address(c), initialBalance);
        Reverter reverter = new Reverter();
        bool ok;
        try c.withdrawAll(address(reverter)) { ok = true; } catch { ok = false; }
        assertTrue(!ok || address(c).balance == 0);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
